mapper.delete:

    DELETE FROM EXT_COO_CERTIFY_FILE
     WHERE COMPANY_CODE = #{COMPANY_CODE}
       AND DIVISION_CODE = #{PARAM_DIVISION_CODE}
       AND VENDOR_CODE = #{PARAM_VENDOR_CODE}
       AND COO_CERTIFY_NO = #{COO_CERTIFY_NO}
       AND FILE_SEQ = CAST(#{FILE_SEQ} AS SMALLINT)

mapper.select:

	SELECT COUNT(*)
	FROM EXT_COO_CERTIFY_MST
	WHERE COMPANY_CODE = #{COMPANY_CODE}
	  AND DIVISION_CODE = #{PARAM_DIVISION_CODE}
	  AND VENDOR_CODE = #{PARAM_VENDOR_CODE}
	  AND COO_CERTIFY_NO = #{COO_CERTIFY_NO}


	SELECT #{PARAM_VENDOR_CODE}
	       || '-'
	       || TO_CHAR(CURRENT_DATE, 'YYYYMMDD')
	       || '-'
	       || COALESCE(
	            MAX(
	                CAST(
	                    SUBSTRING(
	                        REPLACE(COO_CERTIFY_NO, VENDOR_CODE, '')
	                        FROM 11
	                    ) AS INTEGER
	                )
	            ) + 1,
	            1
	          )
	FROM EXT_COO_CERTIFY_MST
	WHERE COMPANY_CODE = #{COMPANY_CODE}
	  AND DIVISION_CODE = #{PARAM_DIVISION_CODE}
	  AND VENDOR_CODE = #{PARAM_VENDOR_CODE}
	  AND AUTO_COO_YN = 'Y'
	  AND SUBSTRING(
	        REPLACE(COO_CERTIFY_NO, VENDOR_CODE, '')
	        FROM 11
	      ) !~ '[A-Za-z]'

mapper.insert:

    INSERT INTO EXT_COO_CERTIFY_DTL (
         COO_CERTIFY_NO
        ,VENDOR_CODE
        ,DIVISION_CODE
        ,COMPANY_CODE
        ,ITEM_CODE
        ,FTA_CODE
        ,WAREHOUSING_NO
        ,WAREHOUSING_SEQ
        ,COO_YN
        ,HS_CODE
        ,RULE_CODE
        ,RVC_RATE
        ,COO_NATION
        ,ISSUE_DATE
        ,APPLY_DATE
        ,END_DATE
        ,CREATE_DATE
        ,CREATE_BY
        ,UPDATE_DATE
        ,UPDATE_BY
    )
    VALUES (
         #{COO_CERTIFY_NO}
        ,#{PARAM_VENDOR_CODE}
        ,#{PARAM_DIVISION_CODE}
        ,#{COMPANY_CODE}
        ,#{ITEM_CODE}
        ,#{FTA_CODE}
        ,#{WAREHOUSING_NO}
        ,#{WAREHOUSING_SEQ}
        ,#{COO_YN}
        ,#{HS_CODE}
        ,#{RULE_CODE}
        ,CAST(NULLIF(REPLACE(CAST(#{RVC_RATE} AS TEXT), '%', ''), '') AS NUMERIC)
        ,#{COO_NATION}
        ,#{ISSUE_DATE}
        ,#{APPLY_DATE}
        ,#{END_DATE}
        ,CURRENT_TIMESTAMP
        ,#{USER_ID}
        ,CURRENT_TIMESTAMP
        ,#{USER_ID}
    )

mapper.update:
    
        UPDATE PO_LEDGER PL
        SET COO_TYPE = #{COO_CERTIFY_TYPE}
           ,COO_CERTIFY_NO = #{COO_CERTIFY_NO}
           ,UPDATE_DATE = CURRENT_TIMESTAMP
           ,UPDATE_BY = #{USER_ID}
        WHERE EXISTS (
            SELECT 1
            FROM EXT_COO_CERTIFY_MST CCM
            INNER JOIN EXT_COO_CERTIFY_DTL CCD
               ON CCD.COO_CERTIFY_NO = CCM.COO_CERTIFY_NO
              AND CCD.VENDOR_CODE = CCM.VENDOR_CODE
              AND CCD.DIVISION_CODE = CCM.DIVISION_CODE
              AND CCD.COMPANY_CODE = CCM.COMPANY_CODE
            WHERE PL.COMPANY_CODE = CCD.COMPANY_CODE
              AND CAST(PL.WAREHOUSING_NO AS TEXT) = CAST(CCD.WAREHOUSING_NO AS TEXT)
			  AND CAST(PL.SEQ AS TEXT) = CAST(CCD.WAREHOUSING_SEQ AS TEXT)
			  AND PL.DIVISION_CODE = CCD.DIVISION_CODE
			  AND PL.VENDOR_CODE = CCM.VENDOR_CODE
			  AND PL.ITEM_CODE = CCD.ITEM_CODE
              AND CCM.COO_CERTIFY_NO = #{COO_CERTIFY_NO}
              AND CCM.VENDOR_CODE = #{PARAM_VENDOR_CODE}
              AND CCM.COMPANY_CODE = #{COMPANY_CODE}
              AND CCM.DIVISION_CODE = #{PARAM_DIVISION_CODE}
        )

mapper.insert:

	INSERT INTO EXT_COO_CERTIFY_FILE (
	     COO_CERTIFY_NO
	    ,VENDOR_CODE
	    ,DIVISION_CODE
	    ,COMPANY_CODE
	    ,FILE_SEQ
	    ,FILE_NAME
	    ,FILE_PATH
	    ,ORIGIN_FILE_NAME
	    ,CREATE_DATE
	    ,CREATE_BY
	    ,UPDATE_DATE
	    ,UPDATE_BY
	    ,EXT_COO_FILE
	)
	VALUES (
	     #{COO_CERTIFY_NO}
	    ,#{VENDOR_CODE}
	    ,#{PARAM_DIVISION_CODE}
	    ,#{COMPANY_CODE}
	    ,(
	        SELECT COALESCE(MAX(FILE_SEQ), 0) + 1
	        FROM EXT_COO_CERTIFY_FILE
	        WHERE COO_CERTIFY_NO = #{COO_CERTIFY_NO}
	          AND VENDOR_CODE = #{VENDOR_CODE}
	          AND COMPANY_CODE = #{COMPANY_CODE}
	     )
	    ,#{FILE_NAME}
	    ,#{FILE_PATH}
	    ,#{ORIGIN_FILE_NAME}
	    ,CURRENT_TIMESTAMP
	    ,#{CREATE_BY}
	    ,CURRENT_TIMESTAMP
	    ,#{UPDATE_BY}
	    ,#{EXT_COO_FILE,jdbcType=BINARY}
	)

mapper.select:

    SELECT FILE_NAME AS "FILE_NAME"
          ,FILE_PATH AS "FILE_PATH"
          ,ORIGIN_FILE_NAME AS "ORIGIN_FILE_NAME"
          ,FILE_SEQ AS "FILE_SEQ"
    FROM EXT_COO_CERTIFY_FILE
    WHERE COMPANY_CODE = #{COMPANY_CODE}
      AND DIVISION_CODE = #{PARAM_DIVISION_CODE}
      AND VENDOR_CODE = #{PARAM_VENDOR_CODE}
      AND COO_CERTIFY_NO = #{COO_CERTIFY_NO}
    ORDER BY FILE_SEQ


    SELECT FILE_NAME AS "FILE_NAME"
          ,FILE_PATH AS "FILE_PATH"
          ,ORIGIN_FILE_NAME AS "ORIGIN_FILE_NAME"
          ,FILE_SEQ AS "FILE_SEQ"
          ,EXT_COO_FILE AS "EXT_COO_FILE"
      FROM EXT_COO_CERTIFY_FILE
     WHERE FILE_SEQ = CAST(#{FILE_SEQ} AS SMALLINT)
       AND COMPANY_CODE = #{COMPANY_CODE}
       AND DIVISION_CODE = #{PARAM_DIVISION_CODE}
       AND VENDOR_CODE = #{PARAM_VENDOR_CODE}
       AND COO_CERTIFY_NO = #{COO_CERTIFY_NO}
